wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm::infer;

struct Node;

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // requires len(in1.date) == 10 — defensively normalize rather than trust it.
        let date = normalize_date(&info.date);

        let summaries: Vec<String> = selected
            .entries
            .iter()
            .filter(|e| e.kept)
            .map(|e| format!("- [{}] {}: {}", category_label(e.category), e.title, e.summary))
            .collect();

        let prompt = format!(
            "Date: {}\nKept items:\n{}",
            date,
            summaries.join("\n")
        );

        let system = "Write a concise overview of today's digest, no more than 600 characters.";

        let raw_overview = infer(system, &prompt, "digest");

        let overview = truncate_chars(&raw_overview, 600);

        Digest {
            date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

/// Ensure the returned date string is exactly 10 characters, per `ensures len(date) == 10`.
fn normalize_date(date: &str) -> String {
    let mut chars: Vec<char> = date.chars().collect();
    if chars.len() > 10 {
        chars.truncate(10);
    } else {
        while chars.len() < 10 {
            chars.push('0');
        }
    }
    chars.into_iter().collect()
}

/// Truncate to at most `max` characters, respecting char boundaries.
fn truncate_chars(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

export!(Node);
